import { color as d3Color } from 'd3-color';

import { getTokenComputedStyle } from '../../core/functions/getTokenComputedStyle.js';
import { DEFAULT_COLOR_STRING_FALLBACK } from '../constants.js';

export const buildRgbaColorWithOpacity = (
  baseColor: string,
  opacity: number = 1,
) => {
  const nameableColor = getTokenComputedStyle(baseColor);
  const convertedColor =
    d3Color(nameableColor) ?? d3Color(DEFAULT_COLOR_STRING_FALLBACK)!;
  convertedColor.opacity = opacity;

  return convertedColor.formatHex8();
};
